/**
 * Drizzle schema entry point. `pnpm db:generate` reads this file.
 *
 * - `auth-schema.ts` is generated by the Better Auth CLI from `auth.cli.ts`;
 *   a team is a Better Auth `organization`, and team roles live in `member`.
 * - The tables below are the interim-foundation tables and the run tables
 *   (`runs`, `run_events`, `run_results`). `run_questions` and `run_reports`
 *   follow the integration contract and land in their own migration.
 *
 * Conventions: ids are text, timestamps are integer milliseconds, JSON
 * columns are text with `mode: "json"`.
 */
import { sql } from "drizzle-orm";
import {
  check,
  index,
  integer,
  primaryKey,
  sqliteTable,
  text,
} from "drizzle-orm/sqlite-core";
import { organization, user } from "./auth-schema";

export * from "./auth-schema";

const now = sql`(cast(unixepoch('subsecond') * 1000 as integer))`;

export const projects = sqliteTable(
  "projects",
  {
    id: text("id").primaryKey(),
    teamId: text("team_id")
      .notNull()
      .references(() => organization.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    // ROI goals chosen for this project; their meaning belongs to the Input team.
    goals: text("goals", { mode: "json" })
      .$type<string[]>()
      .notNull()
      .default(sql`'[]'`),
    createdBy: text("created_by")
      .notNull()
      .references(() => user.id),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .notNull()
      .default(now),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" })
      .notNull()
      .default(now)
      .$onUpdate(() => new Date()),
  },
  (table) => [index("projects_team_id_idx").on(table.teamId)],
);

// One form file per project, stored opaquely: its shape is Ag1 (Input team).
export const projectForms = sqliteTable("project_forms", {
  projectId: text("project_id")
    .primaryKey()
    .references(() => projects.id, { onDelete: "cascade" }),
  formJson: text("form_json", { mode: "json" }).$type<unknown>().notNull(),
  updatedBy: text("updated_by")
    .notNull()
    .references(() => user.id),
  updatedAt: integer("updated_at", { mode: "timestamp_ms" })
    .notNull()
    .default(now)
    .$onUpdate(() => new Date()),
});

// Metadata for uploads held in the private R2 bucket (`FILES`). Deleting a
// project removes these rows; the server must delete the R2 objects too.
export const files = sqliteTable(
  "files",
  {
    id: text("id").primaryKey(),
    projectId: text("project_id")
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    // teams/{teamId}/projects/{projectId}/files/{fileId}
    r2Key: text("r2_key").notNull().unique(),
    name: text("name").notNull(),
    mime: text("mime").notNull(),
    size: integer("size").notNull(),
    description: text("description").notNull(),
    uploadedBy: text("uploaded_by")
      .notNull()
      .references(() => user.id),
    uploadedAt: integer("uploaded_at", { mode: "timestamp_ms" })
      .notNull()
      .default(now),
  },
  (table) => [
    index("files_project_id_idx").on(table.projectId),
    check(
      "files_description_required",
      sql`length(trim(${table.description})) > 0`,
    ),
    check("files_size_nonnegative", sql`${table.size} >= 0`),
  ],
);

// The team's financial defaults (Q2, #88). Append-only: the newest row per
// (team, key) is in force, and a run pins the settings it used.
export const teamSettings = sqliteTable(
  "team_settings",
  {
    id: text("id").primaryKey(),
    teamId: text("team_id")
      .notNull()
      .references(() => organization.id, { onDelete: "cascade" }),
    key: text("key").notNull(),
    valueJson: text("value_json", { mode: "json" }).$type<unknown>().notNull(),
    rationale: text("rationale"),
    source: text("source"),
    // Null for the defaults seeded when the team is created.
    setBy: text("set_by").references(() => user.id),
    effectiveFrom: integer("effective_from", { mode: "timestamp_ms" })
      .notNull()
      .default(now),
  },
  (table) => [
    index("team_settings_team_key_idx").on(
      table.teamId,
      table.key,
      table.effectiveFrom,
    ),
  ],
);

// ---------------------------------------------------------------------------
// Calculation runs (integration contract section 4, Phase 1).
// `run_questions` (ask_user is tabled) and `run_reports` (Phase 2) are not here yet.
// ---------------------------------------------------------------------------

export const RUN_STATUSES = [
  "idle",
  "preflight",
  "running",
  "blocked_on_question",
  "released",
  "gap_list",
  "failed",
  "cancelled",
] as const;

// One row per run. The id is also the workflow instance id. Whether a run
// released a result or a gap list is read from `status`, not stored twice.
export const runs = sqliteTable(
  "runs",
  {
    id: text("id").primaryKey(),
    projectId: text("project_id")
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    status: text("status", { enum: RUN_STATUSES }).notNull(),
    mode: text("mode", { enum: ["real", "stub"] }).notNull(),
    formHash: text("form_hash").notNull(),
    contractVersion: text("contract_version").notNull(),
    formulaVersion: text("formula_version").notNull(),
    settingsVersion: text("settings_version").notNull(),
    startedBy: text("started_by")
      .notNull()
      .references(() => user.id),
    startedAt: integer("started_at", { mode: "timestamp_ms" })
      .notNull()
      .default(now),
    finishedAt: integer("finished_at", { mode: "timestamp_ms" }),
  },
  (table) => [
    // Idempotent start: the newest run for a project and form hash.
    index("runs_project_form_idx").on(
      table.projectId,
      table.formHash,
      table.startedAt,
    ),
    check(
      "runs_status_allowed",
      sql`${table.status} in ('idle','preflight','running','blocked_on_question','released','gap_list','failed','cancelled')`,
    ),
    check("runs_mode_allowed", sql`${table.mode} in ('real','stub')`),
  ],
);

// Append-only audit log. The agent assigns `seq`. Payloads hold ids, hashes,
// step names and error codes only: never prompts, files or keys.
export const runEvents = sqliteTable(
  "run_events",
  {
    runId: text("run_id")
      .notNull()
      .references(() => runs.id, { onDelete: "cascade" }),
    seq: integer("seq").notNull(),
    step: text("step"),
    type: text("type").notNull(),
    payloadJson: text("payload_json", { mode: "json" })
      .$type<unknown>()
      .notNull(),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .notNull()
      .default(now),
  },
  (table) => [primaryKey({ columns: [table.runId, table.seq] })],
);

// The engine's RunOutput: a result in `result_json` or a gap list in
// `gap_list_json`, never both and never neither.
export const runResults = sqliteTable(
  "run_results",
  {
    runId: text("run_id")
      .primaryKey()
      .references(() => runs.id, { onDelete: "cascade" }),
    resultJson: text("result_json", { mode: "json" }).$type<unknown>(),
    gapListJson: text("gap_list_json", { mode: "json" }).$type<unknown>(),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .notNull()
      .default(now),
  },
  (table) => [
    check(
      "run_results_exactly_one",
      sql`(${table.resultJson} is null) <> (${table.gapListJson} is null)`,
    ),
  ],
);
